
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('fixture.uid',true),'')::uuid $$;
CREATE TABLE clubs(id uuid, owner_id uuid, is_public boolean,asset text);
CREATE TABLE club_members(club_id uuid,user_id uuid,status text);
CREATE TABLE unions(id uuid);
CREATE TABLE tables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid,name text,game_type text,stakes text,small_blind numeric(15,2),big_blind numeric(15,2),min_buy_in numeric(15,2),max_buy_in numeric(15,2),max_players integer,current_players integer,status text,is_private boolean,settings jsonb,created_at timestamp with time zone,updated_at timestamp with time zone,game_variant text,enable_straddle boolean,run_it_twice boolean,auto_muck boolean,ante numeric(15,2),allow_rabbit_hunt boolean,allow_run_it_twice boolean,allow_straddle boolean,game_mode character varying(10),is_vip_only boolean,is_anonymous boolean,ban_chat boolean,label_as_new boolean,is_featured boolean,hide_club_name boolean,is_template boolean,bomb_pot_enabled boolean,double_board boolean,triple_board boolean,pineapple_holdem boolean,seven_deuce_enabled boolean,nit_game boolean,cap_enabled boolean,no_rathole boolean,action_time_seconds integer,ante_bb numeric(10,2),career_percent_min integer,maintain_percent_min integer,maintain_hands integer,auto_start_players integer,game_length_hours integer,created_by uuid,calltime_enabled boolean,auto_extension boolean,auto_restart boolean,auto_create_table boolean,auto_utg_straddle boolean,voluntary_straddle boolean,insurance_enabled boolean,run_it_mode character varying(20),rake_percent numeric(5,2),rake_cap_bb numeric(5,2),agent_downline_limit integer,buy_in_authorization boolean,restrict_device boolean,restrict_observers boolean,gps_restriction boolean,ip_restriction boolean,pc_emulator_restriction boolean,photo_rotation_verification boolean,short_description text,accelerated_mtt boolean,all_in_or_fold boolean,custom_rebuy_reentry_cost boolean,number_of_rebuys_reentries integer,add_on_multiplier numeric(3,1),custom_add_on boolean,add_on_break_length_minutes integer,ko_bounty boolean,gtd_prize_pool boolean,final_table_deal boolean,big_blind_ante boolean,authorized_to_register boolean,late_registration_level integer,early_bird_registration boolean,bubble_protection boolean,featured_tournament boolean,min_players_mtt integer,max_players_mtt integer,multi_day_mtt boolean,save_start_time boolean,start_time timestamp with time zone,restart_tournament_every boolean,tournament_schedule boolean,synchronized_breaks boolean,sng_buy_in numeric(10,2),blind_structure character varying(20),payout_structure character varying(50),starting_chips integer,blinds_up_minutes integer,next_step_satellite boolean,sng_custom_buy_in boolean,sng_player_count integer,is_spins boolean,spins_multiplier integer,is_deleted boolean,deleted_at timestamp with time zone,deleted_by uuid,bbj_percent numeric(5,2),tournament_id uuid,live_state jsonb,union_id uuid,big_blind_ante_enabled boolean,straddle_enabled boolean,straddle_type text,max_straddles integer,run_it_twice_enabled boolean,auto_muck_enabled boolean,show_hand_enabled boolean,disconnect_timeout_seconds integer,max_consecutive_timeouts integer,prefer_check_over_fold boolean,time_bank_max_uses integer,time_bank_enabled boolean,ante_enabled boolean,bomb_pot_frequency integer,bomb_pot_ante_multiplier integer,wait_for_big_blind boolean,seven_deuce_amount numeric,hands_dealt bigint,avg_pot numeric(14,2),bomb_pot_double_board boolean,cap_bb numeric(10,2),bomb_pot_board_count smallint,bomb_pot_trigger_mode text,bomb_pot_interval_seconds integer,bomb_pot_min_players smallint,bomb_pot_ante_fixed numeric,first_button_seat integer,bomb_pot_variant text,bomb_pot_next_due_at timestamp with time zone,bomb_pot_sched_state jsonb,bomb_pot_manual_pending boolean,bomb_pot_button_policy text,bomb_pot_announce_seconds integer,min_buy_in_bb integer,max_buy_in_bb integer,min_buyin integer,max_buyin integer,cluster_id uuid,role text,main_index integer,lifecycle text,opened_at timestamp with time zone,live_at timestamp with time zone,break_started_at timestamp with time zone,break_eligible_since timestamp with time zone,promote_pending boolean,observer_show_cards boolean,terminal_closed_at timestamp with time zone,seat_game_scope text,seat_admission_key text,f06_lifecycle bigint,dealing_halted_at timestamp with time zone,dealing_halted_reason text,kill_mode text,kill_threshold_bb smallint,dealing_halt_observed_at timestamp with time zone);
ALTER TABLE tables ALTER COLUMN lifecycle SET DEFAULT 'live';
ALTER TABLE tables ALTER COLUMN is_deleted SET DEFAULT false;
ALTER TABLE cash_cluster_events ADD COLUMN table_id uuid;
CREATE TABLE table_seats(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),table_id uuid,user_id uuid,seat_number int,stack numeric,left_at timestamptz);
ALTER TABLE cash_games ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE cash_games ADD COLUMN union_id uuid,ADD COLUMN created_by uuid;
CREATE FUNCTION fn_caller_session_is_live() RETURNS boolean LANGUAGE sql AS $$ SELECT true $$;
CREATE FUNCTION fn_cash_game_barred_seconds(g uuid,u uuid) RETURNS int LANGUAGE sql AS $$ SELECT CASE WHEN current_setting('fixture.barred',true)=g::text THEN 30 ELSE NULL END $$;
CREATE FUNCTION fn_can_create_games(uuid,uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT true $$;
CREATE FUNCTION is_club_admin(uuid,uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION fn_cash_override_bool(j jsonb,k text,d boolean) RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce((j->>k)::boolean,d) $$;
CREATE FUNCTION fn_cash_override_int(j jsonb,k text,d int) RETURNS int LANGUAGE sql AS $$ SELECT coalesce((j->>k)::int,d) $$;
CREATE FUNCTION fn_cash_stakes_label(numeric,numeric,text) RETURNS text LANGUAGE sql AS $$ SELECT $1::text||'/'||$2::text $$;
CREATE FUNCTION fn_club_union_context(uuid) RETURNS TABLE(own_union_id uuid,member_union_id uuid) LANGUAGE sql AS $$ SELECT NULL::uuid,NULL::uuid $$;
